import { useEffect,useRef, useState } from 'react';
import {localTime} from './timer.js';
import {Swiper, SwiperSlide} from 'swiper/react';
import 'swiper/css';
import DigitalClock from './clocks/digital.jsx';
import ArrowClock from './clocks/arrow.jsx';
import InteractiveClock from './clocks/interactive.jsx';

export default function  Clock ({children,selected,cityLabel,clockFace}) {
  const [time,setTime] = useState(localTime(selected));
  const [clockFaceLoc, setClockFaceLoc] = useState(0);
  const swiperRef = useRef(0);  
   let selEl = 0;

   useEffect(()=>{
     selEl = document.querySelector('#clock-select');
    if(selEl.value === clockFace) {
        if(clockFace=== 'digital') {
            swiperRef.current.swiper.slideTo(0);
        } else if(clockFace === 'arrow') {
            swiperRef.current.swiper.slideTo(1);
        } else if (clockFace=== 'interactive') {
            swiperRef.current.swiper.slideTo(2);
        }
    } else {
        if(selEl.value   === 'digital') {
            swiperRef.current.swiper.slideTo(0);
        } else if(selEl.value === 'arrow') {
            swiperRef.current.swiper.slideTo(1);
        } else if (selEl.value   === 'interactive') {
            swiperRef.current.swiper.slideTo(2);
        }
    }
        if (time.timeZone!=selected) {
           upTime();
        }
        const timeUp = setTimeout(upTime,1000);
        return () => clearTimeout(timeUp);
    })
    function upTime() {
        setTime(localTime(selected));
    }

    return (
        <div className="clock" data-clock={clockFace}>
            <div className="clock-container">    
                <Swiper
                    spaceBetween={50}
                    slidesPerView={1}
                    onSlideChange={() => selEl.value = swiperRef.current.swiper.activeIndex === 0 ? 'digital':swiperRef.current.swiper.activeIndex === 1? 'arrow' :swiperRef.current.swiper.activeIndex === 2? 'interactive' :0 }
                    ref={swiperRef}
                    >     
                    <SwiperSlide><DigitalClock date={time.curDate} time={time} timeCLass={time.timeCLass} cityLabel={cityLabel}/></SwiperSlide> <SwiperSlide><ArrowClock date={time.curDate} time={time} timeCLass={time.timeCLass} cityLabel={cityLabel} /></SwiperSlide><SwiperSlide><InteractiveClock date={time.curDate} time={time} timeCLass={time.timeCLass} cityLabel={cityLabel}/></SwiperSlide>   
                </Swiper>
            </div>
        </div>
    );

}